using System;using System.IO;
class PreflightPureTest{
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static int Main(string[] args){string dir=args[0];Directory.CreateDirectory(dir);string game=Path.Combine(dir,"synthetic.iso"),bios=Path.Combine(dir,"synthetic.bin");File.WriteAllBytes(game,new byte[]{1});using(var s=File.Create(bios))s.SetLength(524288);
 Check(Preflight.Check("",false).State=="Not selected","empty");Check(Preflight.Check(Path.Combine(dir,"absent.iso"),false).State=="Missing or inaccessible","missing");Check(Preflight.Check(game,false).State=="Metadata check passed","game shape");Check(Preflight.Check(bios,true).State=="Metadata check passed","bios shape");Check(Preflight.Check(game,true).State=="Needs attention","wrong bios");string cue=Path.Combine(dir,"synthetic.cue");File.WriteAllText(cue,"FILE \"missing.bin\" BINARY");Check(Preflight.Check(cue,false).State=="Needs attention","missing track");using(var locked=new FileStream(cue,FileMode.Open,FileAccess.ReadWrite,FileShare.None))Check(Preflight.Check(cue,false).State=="Could not check","locked metadata");var r=Preflight.Check(game,false);Check(!r.Detail.Contains(dir)&&r.Detail.Contains("not established"),"identity and privacy");Check(File.ReadAllBytes(game).Length==1&&File.ReadAllBytes(game)[0]==1&&new FileInfo(bios).Length==524288,"unchanged");foreach(byte b in File.ReadAllBytes(bios))Check(b==0,"BIOS bytes unchanged");Console.WriteLine("PASS: preflight empty/missing/invalid/shape-valid/CUE and path-free truthful identity; synthetic files only.");return 0;}
}
